const b="state",v=[{id:"state-emotion-decisions",title:"Lerner y colaboradores · 2015 · Emociones y decisiones · Dossier ST01",url:"https://doi.org/10.1146/annurev-psych-010213-115043",type:"research",finding:"Revisión narrativa de unos 35 años de investigación: las emociones pueden influir en decisiones, incluso cuando vienen de otra situación. Pueden ayudar o perjudicar según la emoción y la decisión.",limitation:"Sin estimación combinada. No valida un mecanismo emocional de tres partes, un ánimo ideal universal ni una pausa de un minuto."},{id:"state-regulation-meta",title:"Webb, Miles y Sheeran · 2012 · Estrategias de regulación emocional · Dossier ST02",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"En 306 comparaciones experimentales, el cambio cognitivo promedió d = 0.36; la modulación de la respuesta, 0.16; y la orientación de la atención, 0.00. Las subcategorías y los resultados emocionales variaron.",limitation:"Principalmente emociones inducidas experimentalmente, no personas en tratamiento. Expresión y experiencia son distintas. No valida preguntas específicas ni una estrategia universalmente superior."},{id:"state-acute-exercise",title:"Reed y Ones · 2006 · Ejercicio puntual y sensación de energía · Dossier ST03",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 estudios, 450 efectos, 13,101 participantes: el cambio promedio corregido de emociones positivas con energía, asociado al ejercicio, fue 0.47. El cambio del control se informó aparte: -0.17.",limitation:"Esos cambios informados por separado no son una comparación aleatorizada entre tratamientos. Mayormente voluntarios sanos con respuestas diversas. No demuestra una dosis de dos minutos ni tratamiento de la depresión."},{id:"state-exercise-mental-health",title:"Singh y colaboradores · 2023 · Actividad física y malestar · Dossier ST04",url:"https://doi.org/10.1136/bjsports-2022-106195",type:"research",finding:"97 revisiones con 1,039 ensayos aleatorizados únicos y más de 128,119 participantes encontraron reducciones promedio de síntomas. Las medianas de los efectos en depresión y ansiedad fueron -0.43 y -0.42.",limitation:"77 revisiones tenían calidad críticamente baja. Los programas prolongados difieren del movimiento breve. El -0.60 en malestar provino de una revisión de seis ensayos con 508 participantes; otro ensayo pequeño no fue significativo."},{id:"state-facial-feedback",title:"Coles, Larsen y Lench · 2019 · Retroalimentación facial · Dossier ST05",url:"https://doi.org/10.1037/bul0000194",type:"research",finding:"138 estudios y 286 efectos: d global = 0.20, IC del 95% de 0.14 a 0.26, combinando experiencia emocional y juicios afectivos. Los efectos fueron pequeños y variables.",limitation:"El recuento publicado es 138, no 136. Algunos efectos en juicios mostraron señales de sesgo de publicación. No establece sonreír como tratamiento fiable del malestar."},{id:"state-cyclic-sighing",title:"Balban y colaboradores · 2023 · Prácticas breves de respiración · Dossier ST09",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 adultos asignados al azar, mayormente de una clase universitaria de psicología en Stanford, practicaron cinco minutos diarios durante 28 días. El modelo favoreció la respiración en emociones positivas.",limitation:"Ensayo exploratorio con registro retrospectivo. No establece superioridad para la ansiedad, una dosis de dos respiraciones, duración del beneficio ni eficacia terapéutica."},{id:"state-affect-labeling",title:"Lieberman y colaboradores · 2007 · Nombrar emociones · Dossier ST11",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"30 adultos sanos nombraron emociones en rostros durante estudios de imagen cerebral. Comparar palabras de emoción con nombres según el género mostró diferencias en una medida de la amígdala, con d = 0.79 informado.",limitation:"No midió recuperación subjetiva del malestar. No establece beneficios de palabras más suaves, nombrar tus emociones, alivio duradero de síntomas ni esta hoja de registro."},{id:"state-gratitude-expressed",title:"Kirca, Malouff y Meynadier · 2023 · Expresar gratitud · Dossier ST13",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"23 estudios y 25 muestras aleatorizadas: bienestar positivo g = 0.22 frente a controles neutros. Frente a actividades válidas de bienestar, g = 0.12, con un intervalo de confianza que incluye cero.",limitation:"Los totales de participantes del artículo se contradicen; no se enseña un N exacto. No valida una rutina matinal, imaginar escenas futuras ni superioridad frente a alternativas creíbles."},{id:"state-positive-self-statements",title:"Wood y colaboradores · 2009 · Afirmaciones positivas sobre ti · Dossier ST12",url:"https://doi.org/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Experimentos iniciales con muestras universitarias sugirieron distintas respuestas a afirmaciones positivas repetidas según la autoestima, incluyendo posibles respuestas peores en algunos participantes.",limitation:"Las réplicas posteriores no reprodujeron los hallazgos de ánimo, autoestima del momento ni moderación. No se establece beneficio ni daño universal. No hay evidencia de superioridad de afirmaciones enfáticas."},{id:"state-mental-contrasting",title:"Wang, Wang y Gai · 2021 · Cumplimiento de metas · Dossier ST15",url:"https://doi.org/10.3389/fpsyg.2021.565202",type:"research",finding:"21 artículos, 24 efectos independientes, 15,907 participantes: el contraste mental con planificación de respuestas mostró g = 0.336. La estimación ajustada por sesgo de publicación fue menor: 0.242.",limitation:"Estudios diversos y posible sesgo de publicación. No valida imágenes del proceso Dickens, vergüenza, exigencias rígidas ni superioridad causal de un formato de aplicación."},{id:"state-self-compassion-motivation",title:"Breines y Chen · 2012 · Motivación para mejorar · Dossier ST16",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Cuatro experimentos breves respaldaron la compatibilidad entre compasión y motivación para mejorar. Tras fallar un examen, el tiempo de estudio promedió 306.5 segundos frente a 203.2 sin recordatorio.",limitation:"El segundo examen no mostró diferencias significativas; la comparación con autoestima fue inconcluyente. No prueba cambios sostenidos, reparación realizada ni eficacia del proceso Dickens."},{id:"state-nhs-panic",title:"NHS · Trastorno de pánico · Dossier ST18",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"El pánico inesperado y recurrente requiere evaluación profesional. Los tratamientos establecidos incluyen terapia cognitivo-conductual y medicamentos.",limitation:"Orientación, no estudio del efecto del acompañamiento. ODA no diagnostica pánico ni puede asumir que dolor de pecho nuevo, desmayo o dificultad respiratoria inexplicada sean ansiedad inofensiva. Busca atención médica o de emergencia adecuada."},{id:"state-affirmation-replication",title:"Flynn y Bordieri · 2020 · Réplica sobre afirmaciones · Dossier ST20",url:"https://doi.org/10.1016/j.jcbs.2020.03.003",type:"research",finding:"Dos experimentos análogos con universitarios no reprodujeron hallazgos previos de ánimo, autoestima del momento ni moderación por autoestima habitual ante afirmaciones positivas.",limitation:"Los resultados nulos no establecen equivalencia ni resuelven cada afirmación. Dos réplicas fallidas dejan inciertos los beneficios previos y las diferencias según autoestima."}];function i(e){const a=e.suggestions;return{schemaVersion:2,revision:2,id:e.id,courseId:b,locale:"es",title:e.title,goal:e.goal,minutes:{learning:6,suggestedAction:a.minutes[0],review:2},direction:{hook:e.hook,reason:{id:`${e.id}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:e.reasons},why:{id:`${e.id}-why`,label:"¿Para qué haría espacio este paso en tu semana?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:`${e.id}-cost`,label:"¿Qué te está costando este patrón?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:e.invitation,instructions:e.instructions,prompts:[],suggestions:a,suggested:{action:a.action[0],minimum:a.minimum[0],minutes:a.minutes[0],cueHint:a.cue[0],placeHint:a.place[0],obstacleHint:e.obstacle,fallbackHint:a.fallback[0],observationHint:a.observation[0]},stopRule:e.stop,accessibleAlternative:e.accessible},result:{question:e.result,observationPrompt:e.observation},judgment:{primary:e.scenario},carry:{takeaway:e.takeaway,followUp:{questionId:`${e.id}-return`,question:e.follow,observationPrompt:e.followObservation,adjustmentPrompt:"¿Qué haría que el próximo intento encaje en tu vida?"}},goDeeper:{sections:e.depth,sourceIds:e.sources}}}const o=[{label:"Hoy",daysFromToday:0},{label:"Mañana",daysFromToday:1}],c=i({id:"state-1",title:"Que una discusión no provoque la siguiente",goal:"Reconoce una emoción que viene de antes y pide algo útil en un entorno seguro.",hook:"¿Sigues con enojo por la última conversación? Dale una oportunidad a lo que necesitas pedir ahora.",reason:"¿Cómo afecta esa emoción anterior a esta conversación?",reasons:["Pedir algo con claridad en casa","Cuidar una relación laboral","Dejar de arrastrar una discusión"],paragraphs:["Una emoción puede venir de antes. El enojo tras un turno difícil puede afectar cómo pides una reparación en casa. La investigación muestra que puede influir en decisiones sobre otros asuntos. No está mal por eso; revisa su origen.","Elige un momento habitual para este curso: antes de llamar, enviar un mensaje o hacer una tarea importante. Nombra la emoción y su posible origen. Después haz algo útil sin exigir calma primero. Atiende el enojo que señala un daño real. Pedir algo claramente, protegerte o buscar apoyo puede importar más que mejorar el ánimo."],example:{title:"Diana pide una reparación",text:"A las 6 p. m., Diana llega irritada tras un turno tenso. Hay una llave de agua que gotea. Nota que su arrendador no provocó la discusión laboral. Sentada a la mesa de la cocina, le pide la reparación con claridad. Él pide una foto. Ella registra su solicitud y envía la foto, todavía irritada."},invitation:"Elige algo útil que pedir en ese momento habitual. Reconoce la emoción y usa tu frase.",instructions:["Nombra dónde pudo empezar esa emoción.","Haz una petición clara en un entorno seguro."],suggestions:{action:["Pedir una reparación con claridad","Pedir una aclaración necesaria","Pedir un apoyo práctico"],minimum:["Enviar una frase con mi petición","Hacer una pregunta concreta","Nombrar un apoyo que necesito"],when:o,cue:["Antes de mi próximo mensaje necesario","En mi próxima conversación segura"],place:["En la mesa de mi cocina, sentado","En una conversación segura por mensajes"],minutes:[2,1,5],fallback:["Usar un mensaje escrito seguro","Elegir otra ocasión segura"],observation:["Mi petición y la respuesta recibida","Si hice la petición"]},obstacle:"Sigo pensando en la conversación anterior",stop:"Si hay peligro real, pausa y busca protección o apoyo.",accessible:"Mantén los ojos abiertos. Sigue sentado, observa el lugar y usa tu forma habitual de comunicarte.",result:"¿Hiciste la petición que elegiste?",observation:"¿Qué pediste exactamente y qué respuesta recibiste después?",scenario:{id:"state-1-carryover-request",scenario:"Quedan dos minutos para reservar reparaciones. Tras un turno tenso, Diana quiere arreglar una fuga esta semana. Su arrendador ha respondido razonablemente antes.",question:"¿Cómo puede empezar bien esta petición?",bestOptionId:"name-and-request",options:[{id:"pause-then-request",text:"Pausar cinco minutos para ordenar sus ideas y luego describir el problema y preguntar por una fecha de reparación.",feedback:"Una pausa definida puede ayudar a ordenar la petición. Aquí perdería el plazo para reservar, aunque puede enviar el mensaje ahora. Diana puede pedir una fecha con datos concretos mientras sigue irritada."},{id:"describe-without-date",text:"Describir brevemente la fuga ahora y dejar que el arrendador proponga qué hacer después.",feedback:"Informa bien del problema y llega dentro del plazo. Deja la fecha sin definir, aunque Diana necesita la reparación esta semana. Pedir una fecha hace visible esa necesidad sin exigir un acuerdo."},{id:"name-and-request",text:"Reconocer el enojo anterior, describir la fuga y pedir claramente una fecha para repararla.",feedback:"Distingue la emoción de lo que sabe sobre esta conversación. Diana hace la petición necesaria y puede registrar la respuesta. No necesita lograr calma ni un acuerdo para haberla hecho."}]},takeaway:"Revisa de dónde viene la emoción. Haz la nueva petición según los hechos de esta situación.",follow:"¿Reconocer esa emoción anterior cambió tu petición, aunque el ánimo siguiera igual?",followObservation:"¿Qué cambió en tu petición o ánimo? Que no cambiara ninguno también es válido.",depth:[{heading:"Las emociones pasan de una decisión a otra",paragraphs:["Lerner y colaboradores revisaron unos 35 años de investigación sobre emociones y decisiones. Describen emociones incidentales: sentimientos que surgen en otra situación e influyen en un juicio nuevo. Las emociones pueden ayudar o dificultar una decisión. Conviene preguntarte si esta emoción aporta información sobre la situación actual o refleja algo anterior. [ST01: state-emotion-decisions]","Esa distinción no te pide descartar el enojo, la tristeza o la preocupación. Un insulto repetido, una necesidad pendiente y un turno agotador son hechos distintos. Nombra la evidencia actual antes de responder. Si necesitas una reparación, pídela. Si necesitas protección, elígela. Esta lección usa una petición cotidiana para mostrar esa decisión. No establece que reconocer la emoción anterior la cambie, garantice cooperación o resuelva una relación insegura."]},{heading:"Una prueba continua, sin examen de ánimo",paragraphs:["Conserva un momento habitual y un rumbo de vida durante el curso. Las próximas lecciones ofrecen herramientas cuando tus registros muestran un problema que podrían atender. No acumulas siete obligaciones. Lo que cuenta es qué pediste, empezaste, cambiaste o dejaste de hacer en ese momento. Puedes haber completado la petición aunque el ánimo siga igual y el mensaje no tenga respuesta.","Webb y colaboradores combinaron 306 comparaciones experimentales de estrategias de regulación emocional. Cambiar una interpretación mostró beneficios promedio, pero variaron las estrategias y los resultados. Algunos midieron expresión; otros, experiencia. Ocultar una emoción no demuestra que desaparezca. Esas comparaciones de laboratorio no validan la tríada de cuerpo, atención y lenguaje ni este ejercicio breve de ODA. [ST02: state-regulation-meta] Anota pocos hechos concretos y elige tu próximo intento según la respuesta y tus circunstancias."]}],sources:["state-emotion-decisions","state-regulation-meta"]}),u=i({id:"state-2",title:"¿Sigues sin energía? Prueba la tarea pendiente",goal:"Prueba una preparación cómoda en tu momento habitual y después haz una parte útil de la tarea.",hook:"Te moviste, pero la energía no llegó. ¿Aun así puedes hacer esa pequeña tarea?",reason:"¿Qué tarea útil espera? ¿Cuándo te serviría más recuperarte?",reasons:["Empezar según lo que puedo hacer","Avanzar en mi trabajo","Dejar espacio para recuperarme"],paragraphs:["Una sesión de ejercicio aeróbico puede aumentar, en promedio, la sensación de energía. Eso difiere de investigar síntomas clínicos mediante programas de actividad. Ninguna investigación establece dos minutos como dosis fiable para cambiar el ánimo.","Conserva tu momento habitual y tarea útil. Si moverte está a tu alcance, prueba una opción cómoda sin cambiar música ni postura. Después intenta el mínimo de la tarea, si conviene. Descansar o empezar sin movimiento puede encajar mejor. Registra preparación y tarea por separado; hacer una no demuestra haber hecho la otra."],example:{title:"La primera diapositiva de Marcos",text:"A las 9 a. m., Marcos está sin energía antes de redactar un informe. Da una caminata corta y cómoda, sin música. De regreso al escritorio, siente la misma energía. Aun así escribe una frase útil para una diapositiva. Registra ambos hechos. Falta trabajo; para la próxima prueba elige empezar sentado."},invitation:"En ese mismo momento, prueba una preparación cómoda si ayuda. Después haz el mínimo de tu tarea.",instructions:["Elige una herramienta o conserva tu preparación habitual sin movimiento.","Haz un paso útil de la tarea según lo que puedas."],suggestions:{action:["Escribir una frase útil para la tarea","Hacer una pequeña corrección laboral","Enviar la petición clara que elegí"],minimum:["Escribir una frase útil","Corregir un punto concreto","Enviar una frase con mi petición"],when:o,cue:["Después del movimiento cómodo opcional","En mi momento de empezar"],place:["Sentado frente a mi mesa de trabajo","En mi espacio de trabajo accesible"],minutes:[2,1,5],fallback:["Empezar sentado, sin movimiento","Descansar y elegir otra ocasión"],observation:["La preparación y la tarea realizadas","Si moverme causó molestias"]},obstacle:"Sigo con poca energía tras prepararme",stop:"Deja de moverte si sientes molestias. Elige descanso o apoyo cuando lo necesites.",accessible:"Muévete sentado, observa el lugar con ojos abiertos o empieza sin movimiento. No tienes que sonreír.",result:"¿Hiciste el mínimo útil de la tarea?",observation:"¿Qué preparación y paso de la tarea hiciste?",scenario:{id:"state-2-unchanged-energy",scenario:"Después de una caminata cómoda, Marcos siente la misma energía, sin molestias. Los datos de su diapositiva están verificados; escribir una frase está a su alcance. Le quedan tres minutos.",question:"¿Qué siguiente paso hace útil la prueba?",bestOptionId:"task-and-record",options:[{id:"timed-seated-start",text:"Dedicar dos minutos a acomodarse sentado y escribir la frase de la diapositiva en el minuto restante.",feedback:"Empezar sentado puede ayudar si moverse incomoda o necesitas esa adaptación para acceder. Marcos no señala ninguna de esas necesidades. Prepararse más consume casi todo el tiempo sin atender un obstáculo identificado."},{id:"task-and-record",text:"Escribir la frase útil, registrar que la energía no cambió y considerar otra preparación cómoda para la próxima prueba.",feedback:"Puede hacer la tarea aunque no llegue el cambio emocional esperado. Marcos sabe qué preparación probó y si empezó. Después puede ajustarla sin esforzarse más para forzar una mejora de ánimo."},{id:"check-and-draft",text:"Pedir a un colega que confirme el dato ya verificado y redactar una frase provisional mientras espera respuesta.",feedback:"Un borrador provisional y otra revisión pueden resolver una duda real. Aquí los datos están verificados. Añade dependencia de una respuesta cuando ya puede escribir y registrar una frase útil."}]},takeaway:"Evalúa con honestidad la preparación. Revisa la tarea útil según lo que hiciste.",follow:"¿La preparación ayudó a empezar, causó molestias o señaló que necesitabas descansar?",followObservation:"Describe ayuda, molestias, necesidad de recuperación o ningún cambio claro, aparte del resultado de la tarea.",depth:[{heading:"Energía inmediata y tratamiento son preguntas distintas",paragraphs:["Reed y Ones reunieron 158 estudios con 13,101 participantes y sesiones individuales de ejercicio aeróbico. Informaron un cambio promedio asociado al ejercicio de 0.47 en afecto positivo activado: energía o alerta, por ejemplo. El cambio del control se informó aparte. El 0.47 no es un efecto terapéutico de una comparación aleatorizada entre ejercicio y control. Variaron las respuestas personales y los procedimientos. [ST03: state-acute-exercise]","Ese resultado no prueba una dosis de dos minutos, energía fiable para todos ni tratamiento de la depresión. Otra revisión general de programas más largos encontró reducciones promedio de síntomas; muchas revisiones incluidas tenían calidad críticamente baja. [ST04: state-exercise-mental-health] Tu preparación breve es una prueba personal opcional. Ajústala al acceso, salud y capacidad. Si registras cansancio o molestias, cambiar la herramienta, pedir apoyo o cuidar tu recuperación puede servirte más que alargar el ejercicio."]},{heading:"Lo opcional puede seguir siendo opcional",paragraphs:["No necesitas una sonrisa, una postura expansiva ni una canción específica para empezar. Coles y colaboradores revisaron 138 estudios y 286 efectos. La estimación global de retroalimentación facial fue pequeña, 0.20, combinando experiencia emocional y juicios. Los efectos variaron; algunos juicios mostraron señales de sesgo de publicación. No establece sonreír como respuesta fiable al malestar. [ST05: state-facial-feedback] No fuerces una sonrisa como preparación.","En esta prueba continua, cambia una preparación a la vez y conserva la tarea útil. Deja las otras condiciones como siempre, en vez de añadir música, postura y movimiento juntos y adivinar qué funcionó. Tu observación ayuda a elegir otra prueba; no aísla un mecanismo biológico ni establece causalidad. Si la tarea está a tu alcance, puedes hacer el mínimo sin sentir más energía. Si conviene recuperarte, registra esa decisión con honestidad sin exigirte mejor ánimo."]}],sources:["state-acute-exercise","state-exercise-mental-health","state-facial-feedback"]}),l=i({id:"state-3",title:"¿Demasiada tensión? Pausa sin perseguir la calma",goal:"Elige una pausa cómoda y después responde de forma útil o da un paso para pedir apoyo.",hook:"Otro ejercicio de respiración puede esperar. Haz espacio para responder con cuidado.",reason:"¿Qué ayudaría a hacer o retrasaría una pausa?",reasons:["Responder con más cuidado","Respetar una señal para parar","Pedir apoyo útil"],paragraphs:["El estudio sobre suspiros usó cinco minutos diarios durante 28 días. No probó dos respiraciones como botón de calma instantánea. Una pausa respiratoria suave es preparación opcional; después viene la acción que elegiste.","Vuelve al mismo momento y respuesta. Sigue sentado en un lugar seguro. Puedes respirar normalmente, con ojos abiertos, y observar el entorno. Si te resulta cómodo, inhala suavemente, toma un poco más de aire y exhala despacio sin forzar. Para si hay mareo, hormigueo, falta de aire o molestias. Elige después respuesta, descanso o apoyo. Síntomas físicos nuevos e intensos requieren evaluación médica, no una explicación de estrés."],example:{title:"Lía y su respuesta pendiente",text:"Después de comer, Lía está tensa ante un correo no urgente en su escritorio. Concentrarse en respirar la incomoda. Con ojos abiertos, observa el marco de la ventana. Después envía una aclaración concreta. Sigue preocupada y no recibe respuesta. Registra la pausa observando el entorno y la frase, sin declarar éxito respiratorio."},invitation:"Elige una pausa cómoda antes de responder. Respirar normalmente y mirar el entorno son opciones válidas.",instructions:["Sigue sentado, sin conducir, lejos del agua y de riesgos de caída.","Después de pausar, haz tu respuesta mínima si conviene."],suggestions:{action:["Enviar una respuesta pensada con cuidado","Pedir una aclaración necesaria","Hacer una petición de apoyo"],minimum:["Enviar una frase con los hechos","Hacer una pregunta clara","Nombrar un apoyo que necesito"],when:o,cue:["Tras una pausa cómoda opcional","Antes de mi próxima respuesta no urgente"],place:["Sentado con seguridad en mi escritorio","Sentado en un lugar seguro y privado"],minutes:[2,1,5],fallback:["Observar el entorno y respirar normalmente","Parar y elegir cómo pedir apoyo"],observation:["La comodidad y la respuesta realizada","Si respeté una señal para parar"]},obstacle:"Concentrarme en respirar me incomoda",stop:"Para si hay mareo, hormigueo, falta de aire o molestias. Respira normalmente. Dolor de pecho nuevo e intenso o dificultad respiratoria inexplicada requieren evaluación médica.",accessible:"Mantén los ojos abiertos, sigue sentado, mira un objeto neutro y respira como siempre.",result:"¿Diste la respuesta que elegiste?",observation:"¿Qué te resultó cómodo y qué respuesta diste después?",scenario:{id:"state-3-uncomfortable-pause",scenario:"Lía deja una prueba respiratoria y respira normalmente, sentada. Sigue sintiendo un mareo que no conoce. Su respuesta no es urgente; un colega cercano puede ayudarla.",question:"¿Qué debe cambiar ahora?",bestOptionId:"stop-and-support",options:[{id:"stop-and-support",text:"Seguir sentada y respirar normalmente, aplazar el correo y pedir al colega ayuda para obtener orientación médica.",feedback:"Hizo bien en parar. El síntoma sigue y es nuevo para ella; buscar ayuda a tiempo tiene prioridad sobre el correo u otra herramienta. Síntomas intensos o peligro inmediato requieren ayuda de emergencia."},{id:"stop-and-look-outward",text:"Seguir sentada y respirar normalmente, fijarse en el marco de la ventana y reevaluar antes de responder.",feedback:"Mirar el entorno puede reemplazar la atención incómoda a la respiración. Aquí el síntoma desconocido persiste tras parar. Ese enfoque por sí solo no debe retrasar la ayuda ni la orientación médica adecuada."},{id:"stop-and-defer",text:"Seguir sentada y respirar normalmente, aplazar el correo hasta mañana y revisar más tarde si pasó el mareo.",feedback:"Aplazar un mensaje no urgente deja tiempo para atenderse. Pero no resuelve un síntoma persistente y desconocido. Pide la ayuda adecuada ahora, sin aplazar también esa evaluación."}]},takeaway:"Parar por seguridad aporta información útil. No necesitas calma para responder con cuidado.",follow:"¿La pausa fue cómoda y ayudó a responder, o necesitas otra herramienta?",followObservation:"Describe por separado comodidad, necesidad de parar o pedir apoyo y la respuesta posterior.",depth:[{heading:"Qué probó el ensayo sobre suspiros",paragraphs:["Balban y colaboradores asignaron al azar a 108 adultos a respiración breve o atención plena. Practicaron cinco minutos diarios durante 28 días. La mayoría venía de una clase universitaria de psicología en Stanford. Fue un estudio exploratorio con registro retrospectivo. El modelo favoreció la respiración en emociones positivas; no estableció superioridad para la ansiedad ni resultados fiables con dos respiraciones. [ST09: state-cyclic-sighing]","El suspiro cíclico estudiado consistía en inhalar despacio, tomar una segunda inhalación más corta y exhalar despacio, sentado o acostado. Esta lección ofrece una prueba cómoda opcional y alternativas de respiración normal. Las opciones de acceso y seguridad son adaptaciones de ODA. No llenes ni vacíes los pulmones hasta forzar, retengas el aire ni aceleres para provocar un efecto. Distingue en tu registro preparación, prueba detenida y respuesta enviada. Ninguna sustituye a las otras."]},{heading:"Respirar no diagnostica un síntoma",paragraphs:["Un ejercicio respiratorio no explica la causa de un síntoma físico. El NHS recomienda evaluación profesional para pánico inesperado recurrente y describe tratamientos establecidos. El límite del curso es claro: ODA educa; no diagnostica ni trata. No asumas que dolor de pecho desconocido, desmayo o dificultad respiratoria inexplicada sean ansiedad inofensiva. Los síntomas nuevos e intensos requieren evaluación médica; el peligro inmediato, ayuda de emergencia. [ST18: state-nhs-panic]","Puedes responder de forma práctica sin cambiar tu respiración. Abre los ojos, observa un objeto neutro, sigue sentado o pide apoyo. Si pausar te incomoda más, déjalo; persistir no es necesariamente avanzar. No tienes que sentir calma antes de pedir algo útil si el entorno es seguro y puedes hacerlo. Tampoco debes continuar la petición si el descanso, la protección o la ayuda de alguien son el siguiente paso adecuado."]}],sources:["state-cyclic-sighing","state-nhs-panic"]}),d=i({id:"state-4",title:"¿Otra vuelta al problema? Haz una pregunta útil",goal:"Convierte una pregunta sobre tu situación habitual en una acción útil o una petición de apoyo adecuada.",hook:"Si otro «por qué» no aporta información, ¿qué respuesta cambiaría tus próximos diez minutos?",reason:"¿Qué pospones al darle otra vuelta a esta situación?",reasons:["Aclarar un problema real","Usar lo que aprendí","Dejar de aplazar una petición útil"],paragraphs:["Una pregunta sirve cuando su respuesta cambia una elección. Preguntar por qué puede revelar una causa, una habilidad pendiente o quién debe reparar un daño. No es dañino por sí mismo. Darle otra vuelta sin nueva información puede dejar tu siguiente paso igual.","En tu momento habitual, pregunta qué necesita aclaración, cambio o apoyo. Responde con un verbo: enviar, corregir, pedir, descansar. La investigación compara estrategias amplias, no este guion. Úsalo como ayuda práctica, actúa si es posible y registra lo que hiciste, aunque la respuesta sonara alentadora."],example:{title:"Óscar encuentra quién debe autorizar",text:"A las 2 p. m., Óscar revisa una solicitud estancada en su escritorio. Preguntar por qué revela que falta quien autorice el presupuesto; no un fracaso personal. Busca el contacto en las notas del proyecto y envía una aclaración. Esa tarde no hay respuesta. Registra pregunta, mensaje y autorización pendiente, sin escribir más preguntas alentadoras."},invitation:"Haz una pregunta útil sobre la misma situación. Haz la acción mínima adecuada que sugiera la respuesta.",instructions:["Conserva la investigación y la responsabilidad cuando importen.","Convierte la respuesta en una petición o corrección real."],suggestions:{action:["Enviar una aclaración necesaria","Corregir un problema identificado","Pedir un recurso que falta"],minimum:["Enviar una frase para aclarar","Corregir un punto real","Nombrar un recurso que falta"],when:o,cue:["Después de responder mi pregunta útil","En mi momento de empezar"],place:["En mi escritorio o teléfono","En una conversación segura por mensajes"],minutes:[2,1,5],fallback:["Pedir ayuda para encontrar la respuesta","Programar una ocasión adecuada para responder"],observation:["La respuesta y la acción realizada","Lo que sigue sin resolverse"]},obstacle:"Sigo analizando sin dar un paso",stop:"Otro ejercicio de reflexión no sustituye la protección ni el apoyo que necesitas.",accessible:"Responde en silencio o con tu forma habitual de comunicarte. Pedir apoyo puede ser la acción útil.",result:"¿Actuaste según la respuesta útil?",observation:"¿Qué reveló tu pregunta y qué hiciste con esa respuesta?",scenario:{id:"state-4-question-to-action",scenario:"Óscar confirma que su solicitud tiene los campos de presupuesto necesarios, pero no llegó a quien autoriza. La persona indicada acepta mensajes de aclaración ahora.",question:"¿Qué completa la pregunta útil?",bestOptionId:"contact-approver",options:[{id:"check-budget-field",text:"Revisar otra vez los campos enviados antes de aclarar, para que quien autoriza reciba una solicitud completa.",feedback:"Revisar campos necesarios puede evitar un mensaje inútil. Óscar ya los confirmó; lo pendiente es entregar la solicitud. Repetir la revisión añade preparación sin resolver ese problema conocido."},{id:"break-then-contact",text:"Descansar cinco minutos y luego enviar la aclaración, sin mezclar su frustración con el mensaje sobre los hechos.",feedback:"Tiene un límite y puede ayudar cuando hace falta descansar. Aquí no se identifica esa necesidad. La aclaración está lista y atiende directamente la autorización pendiente."},{id:"contact-approver",text:"Enviar una aclaración concreta a quien debe autorizar y registrar la respuesta o su ausencia.",feedback:"Convierte la causa identificada en una acción a su alcance. Puede no llegar respuesta; la autorización depende de otra persona. Óscar sí puede registrar si hizo la petición útil."}]},takeaway:"Una respuesta sirve cuando cambia tu siguiente paso de forma útil.",follow:"¿Tu pregunta aclaró algo y cambió tu acción, o solo sonó alentadora?",followObservation:"Nombra qué se aclaró y cambió; también vale que no hubiera información ni cambios nuevos.",depth:[{heading:"Investigar la atención no valida estas preguntas",paragraphs:["Webb y colaboradores reunieron 306 comparaciones experimentales. Las estrategias amplias de cambio cognitivo mostraron un efecto promedio de 0.36 en resultados emocionales. Orientar la atención promedió cerca de cero globalmente, con diferencias entre subcategorías. Incluyeron instrucciones diversas y emociones breves inducidas. No prueban que ciertas preguntas matinales mejoren tu ánimo ni que preguntar por qué o concentrarte en un problema sea generalmente dañino. [ST02: state-regulation-meta]","Usa esa distinción para revisar para qué preguntas. Investigar puede establecer hechos. Revisar responsabilidades puede identificar quién debe responder. Planificar permite nombrar un recurso faltante. Cada cosa puede merecer tiempo. Si la respuesta señala algo posible, hazlo. Si señala una limitación externa, no la conviertas en un problema de actitud. Esta combinación de pregunta y acción de ODA es una adaptación; no un protocolo probado con dosis verificada ni resultado emocional prometido."]},{heading:"Conecta la respuesta con tu prueba",paragraphs:["Tu prueba ya tiene un rumbo, un momento habitual y una respuesta útil. Tenlos presentes. La pregunta debe mejorar la respuesta, sin volverse otro ritual diario. Por ejemplo, la aclaración puede ir a quien debe autorizar; el trabajo, al punto incorrecto; la protección, a una interacción dañina. Pide solo información pertinente para tu siguiente elección.","Las emociones pueden influir en cómo interpretas una respuesta y venir de otro evento. Lerner y colaboradores describen efectos útiles y perjudiciales en decisiones. [ST01: state-emotion-decisions] Registra la evidencia obtenida y lo que hiciste. Una respuesta útil puede dejar pendiente el problema mayor. Si no podías actuar con seguridad, registra esa limitación o elige apoyo. No conviertas una pausa cuidadosa en fracaso ni una pregunta escrita en prueba de la acción posterior."]}],sources:["state-regulation-meta","state-emotion-decisions"]}),p=i({id:"state-5",title:"El mensaje dolió. Conserva los hechos",goal:"Distingue un hecho de un motivo supuesto y luego aclara o protégete en esa misma situación habitual.",hook:"Ese mensaje dolió. Antes de suponer el motivo, revisa las palabras y elige una respuesta segura.",reason:"¿Qué protegería o costaría una respuesta más segura?",reasons:["Usar comentarios sin atacarme","Dejar de aceptar trato injusto","Preguntar antes de suponer motivos"],paragraphs:["Un hecho y su explicación son distintos. «El mensaje contiene un insulto» se puede comprobar. «Quieren arruinar mi carrera» supone un motivo. Otra explicación debe ajustarse a los hechos sin llamar inofensivo al daño.","En ese mismo momento, nombra un hecho y lo que desconoces. Después aclara, corrige, pon un límite o busca apoyo. Una emoción nombrada más suavemente no es necesariamente más precisa. El estudio clásico midió respuestas cerebrales a rostros, no alivio por renombrar el malestar. Prefiere precisión a positividad."],example:{title:"Los mensajes que guardó Nina",text:"A las 4 p. m., Nina recibe otro mensaje insultante del equipo. Sentada en privado, distingue las palabras guardadas de sus suposiciones sobre el motivo. Sigue enojada. En vez de llamarlo malentendido, pregunta a una jefa de confianza cómo denunciar de forma segura. La jefa necesita revisar. Nina registra la petición y protege los mensajes."},invitation:"Usa un hecho para mejorar tu respuesta. Aclara lo desconocido o protégete si el daño está documentado.",instructions:["Distingue los hechos observables de los motivos supuestos.","Haz una aclaración, corrección, petición de apoyo o pon un límite adecuado."],suggestions:{action:["Preguntar cómo pedir apoyo seguro","Enviar una aclaración con los hechos","Corregir un error laboral confirmado"],minimum:["Hacer una petición de apoyo","Preguntar por un hecho","Corregir un punto concreto"],when:o,cue:["Tras revisar un mensaje que me dolió","Antes de mi próxima respuesta prevista"],place:["Sentado en un lugar seguro y privado","En un canal de apoyo de confianza"],minutes:[2,1,5],fallback:["Guardar evidencia y buscar apoyo más seguro","Elegir otra ocasión segura para responder"],observation:["El hecho y la respuesta que usé","Qué evidencia cambió mi interpretación"]},obstacle:"Una explicación positiva ocultaría un daño real",stop:"No llames malentendido al abuso ni al peligro. Elige protección y apoyo.",accessible:"Nombra hechos en silencio, escribe, usa señas o pide ayuda. No exige atención corporal ni palabras más suaves.",result:"¿Diste la respuesta concreta que elegiste?",observation:"¿Qué evidencia concreta usaste y qué respuesta diste después?",scenario:{id:"state-5-documented-insults",scenario:"Nina protegió mensajes con insultos repetidos. Una jefa de confianza está disponible ahora; el portal de denuncias abre mañana. No hay peligro inmediato ni se conoce el motivo.",question:"¿Qué paso usa los hechos y el apoyo disponible?",bestOptionId:"facts-and-support",options:[{id:"copy-and-wait",text:"Hacer otra copia protegida de los insultos guardados y esperar a que mañana abra el portal de denuncias.",feedback:"Conservar evidencia protege. Estos mensajes ya están seguros; otra copia no aporta una protección identificada. La jefa disponible puede aclarar un camino seguro ahora sin exigir contacto con quien los envió."},{id:"facts-and-support",text:"Distinguir los insultos documentados de motivos supuestos y preguntar a alguien de confianza cómo pedir apoyo seguro.",feedback:"Conserva la incertidumbre sobre el motivo y reconoce el daño real. Nina puede protegerse sin probar una intención oculta, cambiar cómo nombra su emoción ni enfrentar directamente a quien envió los mensajes."},{id:"wait-safe-portal",text:"Evitar contactar a quien los envió, esperar al portal de mañana y usar los mensajes guardados para pedir apoyo.",feedback:"Evitar contacto directo y usar un canal de denuncia puede proteger. Aquí hay apoyo de confianza antes. Preguntar ahora por el camino conserva sus opciones; no la obliga a denunciar ni a confrontar."}]},takeaway:"Cambia tu interpretación solo hasta donde permita la evidencia. Después responde como convenga.",follow:"¿Qué evidencia apoyó o cuestionó tu interpretación? ¿Tu respuesta se ajustó a ella?",followObservation:"Nombra el hecho pertinente, lo incierto y si tu respuesta encajó con la evidencia.",depth:[{heading:"Una medida cerebral no es tratamiento del malestar",paragraphs:["Lieberman y colaboradores estudiaron a 30 adultos sanos nombrando emociones en rostros durante un estudio de imagen cerebral. Comparar palabras emocionales y nombres según el género mostró diferencias en una medida de la amígdala. No mostró que cambiar «furioso» por «molesto» reduzca el malestar cotidiano, que nombrar tus emociones tenga ese efecto ni que el beneficio dure. [ST11: state-affect-labeling] Son intervenciones y resultados distintos.","ODA usa aquí hechos, emociones e incertidumbre como ayuda para aclarar tu siguiente elección. Puedes nombrar una emoción fuerte con precisión, no ponerle nombre o guardar la nota en privado. Un insulto documentado sigue siendo insulto aunque después sientas menos enojo. Una respuesta algo tardía puede seguir siendo ambigua aunque ahora tengas mucha ansiedad. Usa lo comprobable, conserva lo desconocido y elige lo que cuide tu seguridad y tu rumbo."]},{heading:"Reinterpretar también permite poner un límite",paragraphs:["Cambiar una interpretación suele llamarse reevaluación. Webb y colaboradores hallaron beneficios promedio en comparaciones experimentales diversas, con diferencias claras entre estrategias y resultados. Eso no vuelve universalmente mejor una explicación positiva. La evidencia no valida esta hoja exacta de un minuto ni justifica ignorar comentarios, limitaciones materiales o daños. [ST02: state-regulation-meta]","Una interpretación justa puede precisar tu responsabilidad: omití este punto y lo corregiré. También puede reducir culpas sin fundamento: desconozco por qué tarda la respuesta; preguntaré. Si hay daño documentado, puede apoyar la protección: no necesito probar un motivo para pedir ayuda. Continúa la misma prueba y registra tu respuesta y la evidencia nueva. Una petición sin respuesta sigue sin respuesta. Parar por seguridad sigue siendo parar. Ninguna necesita una historia más optimista para poder registrarse."]}],sources:["state-affect-labeling","state-regulation-meta"]}),m=i({id:"state-6",title:"¿Las frases positivas suenan falsas? Haz algo útil",goal:"Usa una frase creíble para empezar tu tarea, sin exigir gratitud ni un cambio de ánimo.",hook:"Tu rutina matinal está lista. ¿Ya te ayudó a hacer algo concreto?",reason:"¿Qué sigues aplazando al alargar la rutina?",reasons:["Empezar la acción que elegí","Usar palabras que puedo creer","Prepararme sin alargarlo"],paragraphs:["Las grandes afirmaciones positivas no han demostrado mejorar el ánimo de todos. Los hallazgos iniciales de beneficio y efectos contrarios no se reprodujeron después. Aquí no hay evidencia verificada de que recitarlas con fuerza resuelva eso. Elige una instrucción sencilla que puedas seguir.","En tu momento habitual, prueba «Puedo pedir algo claramente aunque tenga dudas» y envía la petición si conviene. La gratitud opcional debe describir algo real, no un logro imaginado. Omítela si se siente forzada. La frase es preparación. Registra la acción aparte; no necesitas convencerte ni completar un ritual."],example:{title:"La primera petición de Ana",text:"Después de su primera taza de la mañana, a las 8 a. m., Ana tiene dos minutos antes de salir. «Nada me detiene» suena falso. Elige «Puedo preguntar con claridad aunque tenga dudas» y envía la petición pendiente. Hoy omite la gratitud. No recibe respuesta antes de salir. Registra la frase enviada sin llamar fracaso a sus dudas."},invitation:"Haz breve la rutina. Usa una frase creíble y después realiza la acción útil que elegiste.",instructions:["Elige una frase sobre algo que está a tu alcance.","Prueba ahora si conviene o guarda la señal concreta para empezar."],suggestions:{action:["Enviar la petición clara que elegí","Escribir una frase útil para la tarea","Pedir un apoyo práctico"],minimum:["Enviar una frase clara","Escribir una frase útil","Nombrar un apoyo que necesito"],when:o,cue:["Después de mi primera taza","En mi momento de empezar"],place:["En la mesa de mi cocina, sentado","En mi lugar habitual para la tarea"],minutes:[2,1,5],fallback:["Omitir el ritual y usar mi frase","Elegir la próxima ocasión viable"],observation:["Si las palabras llevaron a actuar","Qué preparación retrasó la acción"]},obstacle:"Sigo alargando la preparación",stop:"Omite gratitud, imágenes o frases que aumenten el malestar. Elige apoyo habitual en su lugar.",accessible:"Respira normalmente y mantén los ojos abiertos. Di, escribe, usa señas o sigue la instrucción en silencio.",result:"¿Hiciste la acción después de tu frase?",observation:"¿Qué empezaste a hacer, enviaste o cambiaste después?",scenario:{id:"state-6-believable-start",scenario:"Ana tiene dos minutos antes de salir. Su pregunta está revisada, clara, cortés y lista en un canal seguro. Sigue aplazándola porque quiere sonar segura.",question:"¿Qué versión encaja esta mañana?",bestOptionId:"credible-and-send",options:[{id:"rehearse-and-send",text:"Ensayar el mensaje en voz alta noventa segundos y enviar la pregunta revisada antes de salir.",feedback:"Ensayar con límite puede ayudar ante una petición confusa o nueva. Esta ya está clara y revisada. Ensayar consume casi toda la ocasión sin atender la creencia de que debe sentirse segura primero."},{id:"credible-and-send",text:"Usar una instrucción creíble para preguntar con dudas y enviar la pregunta lista por el canal seguro.",feedback:"Une palabras sobre algo a su alcance con una acción disponible. Ana no necesita creer una gran afirmación, sentir gratitud ni perder sus dudas antes de hacer la petición útil."},{id:"polish-and-send",text:"Redactar un inicio y cierre breves para el mensaje y enviar la pregunta lista antes de salir.",feedback:"Un inicio y cierre añaden cortesía si hace falta. Su pregunta ya comunica la petición. Pulirla deja menos tiempo para enviarla; una instrucción creíble aborda directamente empezar con dudas."}]},takeaway:"Usa palabras suficientemente creíbles para actuar. Deja que la acción aporte la evidencia.",follow:"¿La frase ayudó a actuar, retrasó el paso o no hizo una diferencia clara?",followObservation:"Describe ayuda o demora aparte del resultado de la acción; ninguna diferencia clara también vale.",depth:[{heading:"La evidencia sobre afirmaciones es mixta",paragraphs:["Wood y colaboradores estudiaron afirmaciones positivas repetidas en muestras universitarias. Los hallazgos iniciales sugirieron distintas respuestas según autoestima, incluso peores en algunos participantes. Dos réplicas posteriores de Flynn y Bordieri no reprodujeron los resultados de ánimo, autoestima del momento ni moderación. El límite correcto es evidencia mixta; no que las afirmaciones ayuden o dañen a todos. [ST12: state-positive-self-statements; ST20: state-affirmation-replication]","La evidencia no establece afirmaciones enfáticas acompañadas de movimientos como solución. Aquí ofrecemos una instrucción creíble sobre una conducta como orientación práctica, no tratamiento psicológico probado. Usa tus palabras, omite la frase o elige apoyo. Concreta la tarea y su mínimo para observarlos. Decir una frase sobre una acción futura es prepararte. Enviar la petición, corregir el punto o pedir apoyo es lo que después puedes registrar."]},{heading:"Agradecer tiene límites y es opcional",paragraphs:["Kirca y colaboradores revisaron 23 estudios con 25 muestras aleatorizadas de gratitud expresada. El bienestar positivo mostró un pequeño beneficio promedio frente a controles neutros, con efecto de 0.22. Frente a actividades válidas de bienestar, la estimación fue menor y estadísticamente inconcluyente. [ST13: state-gratitude-expressed] La actividad de comparación importa al evaluar el beneficio aparente.","Esa investigación no establece una rutina de preparación de diez minutos, tres escenas futuras imaginadas, una secuencia matinal óptima ni superioridad frente al tratamiento adecuado. Si agradeces, usa un detalle real que aprecies. No exijas un lado bueno en una pérdida ni gratitud hacia alguien inseguro. Un futuro deseado es posibilidad, no recuerdo ni logro. En tu prueba continua, revisa si la preparación opcional ayudó a la misma acción útil. Déjala si añade demora o molestias."]}],sources:["state-positive-self-statements","state-affirmation-replication","state-gratitude-expressed"]}),g=i({id:"state-7",title:"¿La rutina crece? Elige qué conservar otra semana",goal:"Usa tus registros para conservar, reducir, reemplazar o pausar la misma prueba la próxima semana.",hook:"La rutina crece y la tarea espera. ¿Qué te ayudó a empezar y qué añadió demora?",reason:"¿Qué dejarías de hacer al conservar esta prueba otra semana?",reasons:["Conservar el siguiente paso útil","Cuidar la recuperación necesaria","Dejar un ritual que me retrasa"],paragraphs:["Combinar un futuro deseado, un obstáculo y un plan de respuesta tiene evidencia más directa que imaginar consecuencias catastróficas. Los costos imaginados son predicciones, no hechos. No necesitas vergüenza ni promesas más fuertes.","Revisa tus registros en ese momento habitual. ¿Qué preparación ayudó a responder? ¿Cuál causó molestias, demora o ningún cambio claro? Conserva una versión útil, cambia algo o pausa. Ajusta el mínimo de la próxima semana a tu capacidad y prueba un paso adecuado si es posible. Descanso, protección y apoyo pueden formar parte del plan."],example:{title:"Iván reduce su compromiso",text:"El domingo por la tarde, Iván revisa en su escritorio cómo empezó a trabajar en su portafolio. Mirar el entorno al pausar ayudó; un ritual largo lo retrasó dos veces. Hoy durmió mal, omite el ritual y corrige un pie de foto. Programa ese mismo paso para el martes. Falta terminar el portafolio, pero el plan refleja la evidencia."},invitation:"Usa los registros de tu misma prueba. Conserva una versión útil e intenta su mínimo posible.",instructions:["Revisa los intentos registrados; conserva como desconocidos los resultados que faltan.","Conserva, reduce, cambia o pausa una versión para la próxima semana."],suggestions:{action:["Repetir mi paso útil de la tarea","Hacer mi próxima petición clara","Hacer el paso de recuperación elegido"],minimum:["Corregir un punto útil de la tarea","Usar una frase para pedir algo","Tomar el tiempo de recuperación elegido"],when:o,cue:["En mi momento habitual ya probado","En mi próxima ocasión"],place:["En mi lugar habitual para la tarea","En mi lugar elegido para recuperarme"],minutes:[2,1,5],fallback:["Reducir el paso a lo que puedo","Pausar y elegir cómo pedir apoyo"],observation:["Qué repetí o cambié","Qué obstáculo apareció"]},obstacle:"Mi plan habitual me exige más de lo que puedo",stop:"Omite imágenes de consecuencias que te angustien. Descansar, protegerte y pedir apoyo pueden ser pasos adecuados.",accessible:"Revisa en silencio o con ayuda. Si pausar ayuda, hazlo sentado, con ojos abiertos y sin movimiento.",result:"¿Hiciste el siguiente mínimo que elegiste?",observation:"¿Qué conservaste, cambiaste o pausaste? ¿Qué pasó realmente en tu intento?",scenario:{id:"state-7-capacity-review",scenario:"Iván tiene cinco minutos útiles tras dormir mal. Un pie de foto tiene un error conocido con corrección lista. Entrega la próxima semana; prepararse demasiado retrasó sus dos últimos comienzos.",question:"¿Qué próxima versión encaja con la evidencia?",bestOptionId:"small-caption",options:[{id:"small-caption",text:"Corregir un pie de foto, registrar el intento reducido y elegir la próxima sesión según lo que pueda hacer.",feedback:"Conserva el propósito y ajusta la cantidad a hoy. Iván puede planear otra ocasión según sus registros sin exigir un ritual largo ni energía perfecta."},{id:"sort-next-section",text:"Usar los cinco minutos para ordenar notas de la próxima sección y dejar la corrección conocida para el martes.",feedback:"Ordenar notas prepara otra sección, pero la preparación ha retrasado varias veces su trabajo útil. La corrección actual está lista. Completar esa parte prueba una versión que atiende el obstáculo registrado."},{id:"defer-for-checking",text:"Guardar la corrección para mañana, con descanso, y dedicar estos cinco minutos a programar cuándo revisarla.",feedback:"Aplazar conviene si el cansancio vuelve inadecuada la tarea o hace falta verificar. Aquí la corrección está lista y a su alcance. Programar otra revisión pospone una parte útil disponible."}]},takeaway:"Conserva el propósito. Ajusta la próxima versión a tus intentos y posibilidades actuales.",follow:"¿La nueva versión estuvo a tu alcance? ¿Qué obstáculo la afectó?",followObservation:"Nombra qué encajó, qué se interpuso o por qué convenía recuperarte o cambiar algo.",depth:[{heading:"Planificar obstáculos tiene respaldo; imaginar catástrofes es opcional",paragraphs:["Wang y colaboradores combinaron 24 efectos independientes de 21 artículos con 15,907 participantes. El contraste mental con planificación de respuestas mostró un efecto promedio pequeño a moderado de 0.336 en cumplimiento de metas. Ajustado por sesgo de publicación, fue menor; los resultados variaron. Combina un futuro deseado viable, un obstáculo y un plan de «si ocurre, haré esto». No valida el proceso Dickens, inducir vergüenza ni convertir cada «debería» en «debo». [ST15: state-mental-contrasting]","Elige un obstáculo que respalden tus registros o circunstancias. Si es interno, nombra una respuesta posible. Si es externo, quizá necesites recursos, otro entorno o ayuda. Un costo futuro imaginado sigue siendo predicción. No tienes que revivir recuerdos dolorosos ni imaginar daños crecientes para hacer válido el plan. Esta versión breve basada en registros es adaptación de ODA; su duración es estimada, no una dosis óptima verificada."]},{heading:"Consolida la prueba sin añadir otro ritual",paragraphs:["El curso empezó con un momento habitual y una respuesta útil. Revisa esos intentos antes de decidir qué conservar otra semana. Distingue preparación probada de tarea completada y emoción igual de mínimo fallido. Sin registro no hay resultado conocido. Si la ocasión prevista dependía de algo que no ocurrió, puedes registrar «No hubo ocasión». Basa cada siguiente elección en lo que sabes.","Breines y Chen encontraron que autocompasión y motivación para mejorar podían coexistir en experimentos breves. Tras fallar un examen, el grupo de compasión estudió más que el grupo sin recordatorio. El segundo examen no mostró diferencias significativas; la comparación con autoestima fue inconcluyente. [ST16: state-self-compassion-motivation] Apoya descartar que despreciarte sea necesario para esforzarte. No garantiza cambios sostenidos. La próxima versión puede incluir apoyo, recuperación o dejar un plan inadecuado. Registrar y fijar una revisión mantienen honestas esas decisiones, sin exigir una racha diaria."]}],sources:["state-mental-contrasting","state-self-compassion-motivation"]}),f=[{id:"state-1",practiceCount:3,correct:2,photo:{id:"1758192139097-1e7f30c2498e",alt:"Un hombre cruza una calle tranquila bajo árboles iluminados por el sol"}},{id:"state-2",practiceCount:3,correct:1,photo:{id:"1692933216024-8de20c41321a",alt:"Una mujer camina por una pasarela de madera entre plantas verdes"}},{id:"state-3",practiceCount:3,correct:0,photo:{id:"1763713383838-5cd702c13160",alt:"Una mujer con ojos cerrados se abraza suavemente en un bosque"}},{id:"state-4",practiceCount:3,correct:2,photo:{id:"1543379232-77ee894c85dd",alt:"Una mujer con gorro tejido mira hacia el sol bajo"}},{id:"state-5",practiceCount:3,correct:1,photo:{id:"1534330207526-8e81f10ec6fc",alt:"Un hombre quieto frente a una ventana luminosa"}},{id:"state-6",practiceCount:3,correct:1,photo:{id:"1552838671-0e948f9f69b5",alt:"Una mujer sentada en el pasto verde mira hacia el sol de la mañana"}},{id:"state-7",practiceCount:3,correct:0,photo:{id:"1633210155534-e43f00c1d627",alt:"Una mujer sentada sobre una roca al aire libre escribe en un cuaderno"}}];function y(e,a){const r=f[a],s=e.judgment.primary.options.find(n=>n.id===e.judgment.primary.bestOptionId),t=e.judgment.primary.options.filter(n=>n.id!==s.id).map(n=>n.text);return t.splice(r.correct,0,s.text),{id:r.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.suggested.action,"Registra lo que pasó y elige el próximo intento adecuado."].slice(0,r.practiceCount),reflection:e.direction.reason.label,question:`${e.judgment.primary.scenario} ${e.judgment.primary.question}`,options:t,correct:r.correct,feedback:s.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,photo:r.photo}}const h={lang:"es",id:"state",title:"¿Sigues tenso? Dale espacio a tu próximo paso",subtitle:"7 lecciones. Prueba una respuesta útil con herramientas opcionales para el momento anterior.",description:"Trabaja sobre un mismo momento cotidiano: preparación cómoda, interpretación precisa, acción y revisión. Conserva lo que sirve a tu vida sin exigir mejor ánimo.",scope:"Para adultos que quieren herramientas cotidianas para cambiar ánimo y energía. Es educación, no diagnóstico ni tratamiento. No trata trastornos de ansiedad, pánico ni depresión, ni sustituye terapia o medicamentos. Para cualquier ejercicio respiratorio si sientes mareo, sensación de desmayo, hormigueo o falta de aire. Respira normalmente y siéntate. Si tienes una afección cardíaca o pulmonar o estás embarazada, consulta con un profesional antes de probar respiración para activarte. Nunca la practiques conduciendo ni en el agua. Si estás en crisis o piensas hacerte daño, contacta al número local de emergencias (911 en EE. UU., 112 en Turquía y gran parte de Europa).",outcome:"Una respuesta útil en un momento habitual, registros honestos y un plan semanal ajustado a lo que puedes hacer.",photo:{id:"1500080628126-901233e80205",alt:"Una mujer de pie en un muelle de madera al atardecer levanta una mano hacia la luz"},lessons:[c,u,l,d,p,m,g].map(y)},j=Object.freeze(Object.defineProperty({__proto__:null,COURSE:h,SOURCES:v,STATE_1_V2:c,STATE_2_V2:u,STATE_3_V2:l,STATE_4_V2:d,STATE_5_V2:p,STATE_6_V2:m,STATE_7_V2:g},Symbol.toStringTag,{value:"Module"}));export{j as s};
